// GENERATED from the packaged seed for `ui-tree` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/shared/ui/layouts/Tree` after the original module was retired. Regenerate with `npm run emit:records`.
// Tree, AS GRAPH SOURCE (#3692, epic #3604) — the design-studio graph renderer authored as DATA. Its
// `provides: "@/shared/ui/layouts/Tree"` makes the runtime loader vendor THIS over the bundled module (registered code
// is the fallback). CTX-free. Transcribed verbatim; deps stay registered code.
// Tree — the Layouts-tier template for tree-shaped data (#2476, epic #2197): org charts, file
// systems, category hierarchies. ONE component, two variants over the same recursive `nodes` prop:
//
//   • "indented" (default, file-explorer style) — collapsible nested rows (chevron toggle, depth
//     indentation, selection) in a MasterDetail rail, beside a detail panel for the selected node.
//     The ideal for DEEP / NAVIGATIONAL trees.
//   • "layered" (org-chart style) — a top-down layered chart riding the SHARED graph stack: the
//     pure `layoutTree` (layerDag #2214 + orderLayers #2418, see treeLayout.ts), the shared edge
//     grammar (`graphEdge` #2222, perimeter-anchor routing — the top-down precedent set by the
//     Design Studio composition graph #2455), and GraphCanvas + useGraphViewport (#2208) for
//     pan/zoom. The ideal for PRESENTATIONAL hierarchies.
//
// Selection is controlled (`selectedId` + `onSelect`) or uncontrolled (`defaultSelectedId`, the
// MasterDetail-tier idiom); expansion is uncontrolled (`defaultCollapsedIds`, `onToggle` notified).
// The `detail` slot (a node, or a render fn of the selected node) is the rail's detail column when
// indented and the canvas inspector when layered. Pure/presentational — data in via props only.
import { useEffect, useMemo, useState, type CSSProperties, type ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Text } from "@/shared/ui/typography/Text";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import { MasterDetail } from "@/shared/ui/layouts/MasterDetail";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { flattenTree, layoutTree, TREE_NODE_W, TREE_NODE_H, type TreeNodeData } from "@/shared/ui/layouts/treeLayout";

export type { TreeNodeData } from "@/shared/ui/layouts/treeLayout";

export type TreeVariant = "indented" | "layered";

export interface TreeProps {
  /** The tree roots — a recursive forest of { id, label, meta?, children? }. Ids must be unique. */
  nodes: TreeNodeData[];
  /** "indented" (default): collapsible rows + detail. "layered": top-down pan/zoom chart. */
  variant?: TreeVariant;
  /** Controlled selection — the selected node id (pair with onSelect). Omit for uncontrolled. */
  selectedId?: string | null;
  /** Uncontrolled: the initially selected node id. */
  defaultSelectedId?: string;
  /** Fires when a node is clicked (both modes; uncontrolled also updates the internal selection). */
  onSelect?: (id: string) => void;
  /** Detail panel for the selected node — a node, or a render fn of the selected TreeNodeData.
   *  Indented: the MasterDetail detail column; layered: the canvas inspector. */
  detail?: ReactNode | ((node: TreeNodeData | undefined) => ReactNode);
  /** Optional toolbar — full-width above the rail+detail (indented) / in the canvas toolbar row,
   *  before the zoom cluster (layered). */
  toolbar?: ReactNode;
  /** Indented: branch ids that start collapsed (expansion is uncontrolled). Default: all expanded. */
  defaultCollapsedIds?: string[];
  /** Fires when a branch toggles; `expanded` is the NEW state. */
  onToggle?: (id: string, expanded: boolean) => void;
  /** Indented: px of indentation per depth level. Default 16. */
  indent?: number;
  /** Indented: rail width in px (the starting width when `resizable`). Default 260. */
  railWidth?: number;
  /** Indented: opt into a drag-resizable rail (MasterDetail's splitter). Default false. */
  resizable?: boolean;
  /** Layered: inspector width in px when `detail` is provided. Default 300. */
  detailWidth?: number;
  /** Extra class on the root (a page scoping hook). */
  className?: string;
}

const ELLIPSIS: CSSProperties = { overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" };

export function Tree({
  nodes, variant = "indented",
  selectedId, defaultSelectedId, onSelect,
  detail, toolbar,
  defaultCollapsedIds, onToggle,
  indent = 16, railWidth = 260, resizable = false, detailWidth = 300,
  className,
}: TreeProps) {
  // Selection — controlled when the `selectedId` prop is present (may be null = none), else internal.
  const [innerSelected, setInnerSelected] = useState<string | null>(defaultSelectedId ?? null);
  const controlled = selectedId !== undefined;
  const selected = controlled ? selectedId : innerSelected;
  const select = (id: string) => {
    if (!controlled) setInnerSelected(id);
    onSelect?.(id);
  };

  // Expansion (indented) — uncontrolled: everything expanded except `defaultCollapsedIds`.
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(() => new Set(defaultCollapsedIds));
  const toggle = (id: string) => {
    const expanding = collapsed.has(id);
    const next = new Set(collapsed);
    if (expanding) next.delete(id); else next.add(id);
    setCollapsed(next);
    onToggle?.(id, expanding);
  };

  const flat = useMemo(() => flattenTree(nodes), [nodes]);
  const selectedNode = flat.find((f) => f.node.id === selected)?.node;
  const detailNode = typeof detail === "function" ? detail(selectedNode) : detail;

  // The layered chart's world + viewport. Hooks always run (rules of hooks); they only drive the
  // layered variant, and the effect re-fits when the tree (world) changes.
  const layout = useMemo(() => layoutTree(nodes), [nodes]);
  const vp = useGraphViewport(layout.world);
  const { fit } = vp;
  useEffect(() => {
    if (variant === "layered") fit();
  }, [variant, fit, layout.world.w, layout.world.h]);

  if (variant === "layered") {
    return (
      <GraphCanvas
        vp={vp} world={layout.world} grid className={className}
        toolbar={
          <>
            {toolbar}
            <Spacer />
            <ZoomControls vp={vp} />
            <IconButton aria-label="fit tree" title="Fit" onClick={() => fit()}>⤢</IconButton>
          </>
        }
        inspector={detailNode ? (
          <Box pad={16} style={{
            flex: `0 0 ${detailWidth}px`, width: detailWidth, minWidth: 0,
            borderLeft: "1px solid var(--border-soft)", overflowY: "auto",
          }}>
            {detailNode}
          </Box>
        ) : undefined}
      >
        <svg width={layout.world.w} height={layout.world.h}
          style={{ position: "absolute", left: 0, top: 0, pointerEvents: "none", overflow: "visible" }}>
          {layout.edges.map((e) => {
            const a = layout.pos.get(e.from), b = layout.pos.get(e.to);
            if (!a || !b) return null;
            // The shared line-type (#2222) with perimeter-anchor routing — the reading that works for
            // a layered TOP-DOWN flow (the side-port router is horizontal-only; see DesignsWorkbench).
            const g = graphEdge({ ...a, w: TREE_NODE_W, h: TREE_NODE_H }, { ...b, w: TREE_NODE_W, h: TREE_NODE_H });
            return (
              <g key={e.id}>
                <path d={g.d} stroke="var(--border)" strokeWidth={1.5} fill="none" />
                <path d={g.arrow} fill="var(--border)" />
              </g>
            );
          })}
        </svg>
        {flat.map(({ node }) => {
          const p = layout.pos.get(node.id);
          if (!p) return null;
          const isSelected = selected === node.id;
          return (
            // data-node: the canvas ignores pans/backdrop-clicks that start on a node (#2208).
            <Stack key={node.id} data-node={node.id} data-selected={isSelected || undefined}
              gap={2} justify="center"
              onClick={() => select(node.id)}
              style={{
                position: "absolute", left: p.x, top: p.y, width: TREE_NODE_W, height: TREE_NODE_H,
                padding: "0 12px", borderRadius: 8, cursor: "pointer",
                background: isSelected ? "var(--accent-soft)" : "var(--bg-elev)",
                border: `1px solid ${isSelected ? "var(--accent)" : "var(--border)"}`,
              }}
            >
              <Text size={12} weight={600} style={ELLIPSIS}>{node.label}</Text>
              {node.meta && <Text size={10} tone="dim" mono style={ELLIPSIS}>{node.meta}</Text>}
            </Stack>
          );
        })}
      </GraphCanvas>
    );
  }

  // ── indented (file-explorer) — collapsible rows in a MasterDetail rail + the detail column ──
  const rows = (list: readonly TreeNodeData[], depth: number): ReactNode[] =>
    list.flatMap((n) => {
      const branch = !!n.children?.length;
      const isCollapsed = collapsed.has(n.id);
      const isSelected = selected === n.id;
      const row = (
        <Row key={n.id} role="treeitem" aria-selected={isSelected}
          aria-expanded={branch ? !isCollapsed : undefined}
          tabIndex={0} gap={4}
          onClick={() => select(n.id)}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") { e.preventDefault(); select(n.id); }
          }}
          style={{
            padding: "4px 8px", paddingLeft: 6 + depth * indent, borderRadius: 6, cursor: "pointer",
            background: isSelected ? "var(--accent-soft)" : "transparent",
            border: `1px solid ${isSelected ? "var(--accent-dim)" : "transparent"}`,
          }}
        >
          {branch ? (
            <IconButton size="xs" aria-label={`${isCollapsed ? "expand" : "collapse"} ${n.label}`}
              onClick={(e) => { e.stopPropagation(); toggle(n.id); }}>
              <Text as="span" size={9} tone="muted" style={{
                display: "inline-block", transition: "transform .12s ease",
                transform: isCollapsed ? "none" : "rotate(90deg)",
              }}>▶</Text>
            </IconButton>
          ) : (
            <Box as="span" style={{ display: "inline-block", width: 16, flex: "none" }} />
          )}
          <Text size={12} style={{ minWidth: 0, ...ELLIPSIS }}>{n.label}</Text>
          {n.meta && <Text size={10} tone="dim" mono style={{ marginLeft: "auto", flex: "none" }}>{n.meta}</Text>}
        </Row>
      );
      return branch && !isCollapsed ? [row, ...rows(n.children as TreeNodeData[], depth + 1)] : [row];
    });

  return (
    <MasterDetail
      className={className} toolbar={toolbar}
      railWidth={railWidth} railPad={8} resizable={resizable}
      rail={<Stack role="tree" gap={2}>{rows(nodes, 0)}</Stack>}
      detail={detailNode ?? null}
    />
  );
}

// GENERATED from the packaged seed for `labelchip` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/shared/ui/data/LabelChip` after the original module was retired. Regenerate with `npm run emit:records`.
// A GitHub issue/PR label chip (#1493) — colored pill with a dot, tinted from the label's
// 6-hex color. Consolidates the near-identical copies in the planner Issues / ProjectBoard views.

import type { GhLabel } from "@/shared/lib/github/types";
import { Chip } from "@/shared/ui/data/Chip";

export function LabelChip({ label }: { label: GhLabel }) {
  // A GitHub label's colour is dynamic (6-hex) → the Chip `color` path. bg/border alphas approximate
  // the old `${color}22`/`${color}55` tints.
  return (
    <Chip color={`#${label.color}`} dot gap={4} padding="1px 6px" fontSize={9} bgAlpha={87} borderAlpha={67}>
      {label.name}
    </Chip>
  );
}

// GENERATED from the packaged seed for `ui-activity-feed` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/shared/ui/data/ActivityFeed` after the original module was retired. Regenerate with `npm run emit:records`.
// ActivityFeed, AS GRAPH SOURCE (#4235, epic #3604) — one of the eight shared/ui components the batches
// #3660-#3692 left behind: reached by packaged records, provided by none. Its
// `provides: "@/shared/ui/data/ActivityFeed"` makes the runtime loader vendor THIS source wherever a graph
// component imports that specifier (the registered module is the fallback). Transcribed verbatim; the
// CSS import is dropped (the host owns the stylesheet) and specifiers are absolute. Deps stay code.
import type { ReactNode } from "react";
import { Avatar } from "@/shared/ui/data/Avatar";
import { timeAgo } from "@/shared/lib/core/format";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

/** One row of the activity feed — the normalized shape shared by the github cross-repo feed and the
 *  planner cross-project feed. */
export interface ActivityItem {
  login: string;
  action: string;
  target: string;
  repo: string;
  createdAt: string;
}

/** The "Recent activity" striped feed: a `.card` with a header (title + hint + optional control) and
 *  a list of `Avatar · action · target · repo · timeAgo` rows. Unifies CrossRepoActivity (github)
 *  and CrossProjectActivity (planner), which were byte-identical apart from the hint, the optional
 *  filter, and the action-column width. The `action → color` map is passed in (`tone`) so each
 *  caller keeps its own EVENT_TONE rather than coupling the two. */
export function ActivityFeed({ items, hint, loading, tone, right, actionWidth = 80 }: {
  items: ActivityItem[];
  hint: string;
  loading: boolean;
  tone: Record<string, string>;
  /** Optional header control on the right (e.g. a filter select). */
  right?: ReactNode;
  /** Width of the action column in px (github uses 70, planner 80). */
  actionWidth?: number;
}) {
  return (
    <div className="card" style={{ padding: "14px 16px" }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 10 }}>
        <h3 style={{ margin: 0 }}>Recent activity</h3>
        <span className="hint">{hint}</span>
        {right != null && <><div style={{ flex: 1 }} />{right}</>}
      </div>
      {loading && items.length === 0 && (
        // Shimmer rows while the feed's source loads (#2234) — keeps the card's shape, not a blank body.
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} h={40} radius={6} />)}
        </div>
      )}
      {!loading && items.length === 0 && (
        <EmptyState size="sm" iconVariant="dashed" icon="◔" title="No recent activity"
          description="Recent events across your repos surface here." style={{ padding: "20px 12px" }} />
      )}
      {items.length > 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 1, borderRadius: 6, border: "1px solid var(--border-soft)", overflow: "hidden" }}>
          {items.map((e, i) => (
            <div key={i} style={{
              padding: "10px 12px",
              background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)",
              display: "grid", gridTemplateColumns: `22px ${actionWidth}px 1fr 110px 50px`,
              gap: 10, alignItems: "center", fontSize: 11,
            }}>
              <Avatar login={e.login} />
              <span className="mono" style={{ fontSize: 10.5, color: tone[e.action] ?? "var(--fg-muted)" }}>{e.action}</span>
              <span style={{ color: "var(--fg)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{e.target}</span>
              <span className="mono" style={{ fontSize: 10, color: "var(--fg-dim)" }}>{e.repo}</span>
              <span className="mono" style={{ fontSize: 10, color: "var(--fg-dim)", textAlign: "right" }}>{timeAgo(e.createdAt)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// GENERATED from the packaged seed for `keyvaluelist` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/shared/ui/data/KeyValueList` after the original module was retired. Regenerate with `npm run emit:records`.
// KeyValueList — the read-only label : value property list (#2475). The key-value archetype of the
// row vocabulary (#1865 siblings: CardListRow for card lists, DataTableRow for columnar tables): one
// aligned two-column grid of `{ k, v }` rows — a detail summary, a config/property panel, an
// inspector's facts block. It exists because nothing else in the kit renders a keyed RECORD:
// StatTile is a single KPI pair, the Field controls are editable inputs, RoleTierChips is
// domain-fixed. Loading renders shimmer value placeholders in place (#2302/#2234).
import { Fragment, type ReactNode } from "react";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

/** One property row — a label (`k`) and its value (`v`). */
export interface KeyValueItem {
  k: ReactNode;
  v: ReactNode;
}

export interface KeyValueListProps {
  /** The { k, v } rows, in display order. */
  items: KeyValueItem[];
  /** Fixed label column width in px. */
  labelWidth?: number;
  /** Render values in the mono font (ids, paths, config values). */
  mono?: boolean;
  /** Render shimmer value placeholders (labels stay) while the record's source loads (#2302). */
  loading?: boolean;
  className?: string;
}

/** The label : value property list — a `labelWidth px · 1fr` grid, one row per item. */
export function KeyValueList({ items, labelWidth = 120, mono, loading, className }: KeyValueListProps) {
  return (
    <div
      className={className}
      style={{
        display: "grid",
        gridTemplateColumns: `${labelWidth}px 1fr`,
        rowGap: 7,
        columnGap: 12,
        alignItems: "baseline",
      }}
    >
      {items.map((it, i) => (
        <Fragment key={i}>
          <span
            style={{
              fontFamily: "var(--mono)",
              fontSize: 10,
              textTransform: "uppercase",
              letterSpacing: ".05em",
              color: "var(--fg-muted)",
            }}
          >
            {it.k}
          </span>
          {loading ? (
            <Skeleton h={11} w="60%" radius={4} />
          ) : (
            <span style={{ fontSize: 12, color: "var(--fg)", ...(mono ? { fontFamily: "var(--mono)" } : {}) }}>
              {it.v}
            </span>
          )}
        </Fragment>
      ))}
    </div>
  );
}

// GENERATED from the packaged seed for `ui-pane` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/shared/ui/overlay/Pane` after the original module was retired. Regenerate with `npm run emit:records`.
// Pane, AS GRAPH SOURCE (#3684, epic #3604) — a shared/ui overlay/layout container authored as DATA.
// `provides: "@/shared/ui/overlay/Pane"` makes the runtime loader vendor THIS over the bundled module (registered code
// is the fallback). CTX-free, so a fresh compile has no identity split. Transcribed verbatim.
// Pane (#1824) — the ONE detail/editor pane. A single header / scrollable-body / footer frame
// shared by every "select an item → edit its fields" surface. Two modes:
//   - mode="drawer": a slide-over (scrim + slide-in) — replaces the per-feature DrawerSlideOver +
//     the hand-rolled SkillDrawer chrome. Renders content only while `open`.
//   - mode="inline": the same frame filling its container — for master-detail editors (Automations,
//     the planner pane).
// The footer is either supplied (`footer` slot) or, in drawer mode, the standard draft/remove bar
// every editor shares (cancel/done while drafting, remove/done for an existing item). Pairs with
// the `useDraft` hook for the selection/draft state.
import { type ReactNode } from "react";
import { IconButton } from "@/shared/ui/controls/IconButton";

export interface PaneProps {
  /** "drawer" = slide-over (scrim + slide-in); "inline" = fills its container. Default "drawer". */
  mode?: "drawer" | "inline";
  /** Drawer mode: drives the scrim/slide open state + gates body render. Default true (inline ignores it). */
  open?: boolean;
  /** Top-zone content (drawer mode auto-appends a close button after it). */
  header?: ReactNode;
  /** Body content — pass via `body` or as children. */
  body?: ReactNode;
  children?: ReactNode;
  /** Custom footer. When omitted in drawer mode, the standard draft/remove bar is rendered. */
  footer?: ReactNode;
  // ── Standard drawer footer wiring (used when `footer` is not supplied) ──
  onClose?: () => void;
  onRemove?: () => void;
  isDraft?: boolean;
  onCommit?: () => void;
  /** Disable the draft "done" button (e.g. a required field is empty). */
  commitDisabled?: boolean;
  /** Drop the body's default padding — for bodies whose sections supply their own (e.g. full-bleed
   *  divider rows). */
  flush?: boolean;
  /** Inline mode only: render children directly in the flex-column frame with NO styled
   *  head/body/foot wrappers — for content panes whose zones bring their own chrome (e.g. the
   *  planner `ProjectPane`: progression rail, phase header, advance bar). The editor drawers and the
   *  styled inline editors use the default framed layout. */
  bare?: boolean;
  /** Extra class on the frame element (the drawer aside / the inline section). */
  className?: string;
}

/** The standard drawer footer: cancel/done while drafting, remove/done for an existing item. */
function StandardFooter({ isDraft, onClose, onRemove, onCommit, commitDisabled }: PaneProps) {
  return isDraft ? (
    <>
      <button className="btn ghost" onClick={onClose}>cancel</button>
      <div className="spacer" />
      <button className="btn primary" disabled={commitDisabled} onClick={onCommit}>done</button>
    </>
  ) : (
    <>
      <button className="btn ghost danger" onClick={onRemove}>remove</button>
      <div className="spacer" />
      <button className="btn primary" onClick={onClose}>done</button>
    </>
  );
}

export function Pane(props: PaneProps) {
  const { mode = "drawer", open = true, header, body, children, footer, onClose, flush, bare, className } = props;
  const content = body ?? children;
  const bodyClass = "pane-body" + (flush ? " flush" : "");
  const foot = footer !== undefined
    ? footer
    : mode === "drawer" ? <StandardFooter {...props} /> : null;

  if (mode === "inline") {
    const cls = className ? `pane-inline ${className}` : "pane-inline";
    // Bare: the content pane owns its own zones (header/body/footer chrome) — the Pane is only the
    // flex-column frame. Used by ProjectPane so it joins the one Pane component without restyling.
    if (bare) return <section className={cls}>{content}</section>;
    return (
      <section className={cls}>
        {header != null && <div className="pane-head">{header}</div>}
        <div className={bodyClass}>{content}</div>
        {foot != null && <div className="pane-foot">{foot}</div>}
      </section>
    );
  }

  return (
    <>
      {/* eslint-disable-next-line jsx-a11y/no-static-element-interactions, jsx-a11y/click-events-have-key-events -- drawer scrim mouse-dismiss; the drawer has a keyboard-reachable close button */}
      <div className={"pane-scrim" + (open ? " on" : "")} onClick={onClose} />
      <div className={"pane-drawer" + (open ? " on" : "") + (className ? " " + className : "")}>
        {open && (
          <>
            <div className="pane-head">
              {header}
              <IconButton aria-label="close" onClick={onClose} />
            </div>
            <div className={bodyClass}>{content}</div>
            {foot != null && <div className="pane-foot">{foot}</div>}
          </>
        )}
      </div>
    </>
  );
}

