<TablePage
  title="Sessions" hint="today"
  columns={[
    { key: "name", label: "Session" },
    { key: "state", label: "State", width: "90px" },
  ]}
  rows={sessions.map((s) => ({ id: s.id, cells: { name: s.name, state: s.state } }))}
  onSelect={setSelected}
/>

