/** POSIX single-quote a shell argument (wrap in '…', escaping embedded quotes). Newlines survive
 *  inside single quotes, so a multi-line kickoff passes through `--message` intact. */
function shQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
