// GENERATED from the packaged seed for `viz-registry.ts` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/features/algorithms/viz/registry` after the original module was retired. Regenerate with `npm run emit:records`.
// The pluggable structure-renderer registry (#3176, epic #3171) — the injection point every per-structure
// renderer (#3178–#3185) plugs into WITHOUT editing the player. The player takes a `RendererRegistry`
// (a `Partial<Record<StructureName, StructureRenderer>>`) and dispatches each panel to its structure's
// renderer, or the `fallbackRenderer` when none is registered — so a missing renderer degrades, never
// crashes.
//
// A renderer for structure `S` is a React component over that structure's OWN frame type (`FrameOf<S>`),
// so a `StructureRenderer<"array">` receives an `ArrayFrame`. The registry map is typed per-key, so
// authoring is type-safe: `const registry: RendererRegistry = { array: ArrayView }`.

import type { ComponentType } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import type { FrameOf, StructureFrame, StructureName } from "@/features/algorithms/lib/trace";

/** A renderer for structure `S` — a React component over that structure's frame type (`FrameOf<S>`).
 *  Defaulting `S` to the whole union yields the erased shape the player dispatches through
 *  (a component over any `StructureFrame`), which the {@link fallbackRenderer} satisfies. */
export type StructureRenderer<S extends StructureName = StructureName> = ComponentType<{ frame: FrameOf<S> }>;

/** The injected map the player consumes — a per-structure renderer for zero or more structures. Each
 *  entry is typed to its own frame (`array` → a renderer over `ArrayFrame`). Equivalent to
 *  `Partial<Record<StructureName, StructureRenderer>>` but key-precise. The renderer issues add entries
 *  here; the player never changes. */
export type RendererRegistry = { [S in StructureName]?: StructureRenderer<S> };

/**
 * Resolve the renderer for a panel's structure — the registered one, else the {@link fallbackRenderer}.
 * The single, guarded cast site: the player looks a renderer up by the panel's OWN `structure`, so the
 * runtime frame always matches the resolved renderer's narrowed frame type even though the map's union
 * value type can't prove it statically.
 */
export function resolveRenderer(registry: RendererRegistry, structure: StructureName): StructureRenderer {
  return (registry[structure] as StructureRenderer | undefined) ?? fallbackRenderer;
}

/**
 * The default renderer for any structure with no registered renderer — prints the structure name + a
 * JSON dump of the frame. Keeps the player useful before the concrete renderers (#3178–#3185) land, and
 * makes an unregistered structure legible instead of a crash.
 */
export const fallbackRenderer: StructureRenderer = ({ frame }: { frame: StructureFrame }) => (
  <Stack gap={4} className="trace-fallback">
    <Eyebrow size={10}>{frame.structure}</Eyebrow>
    <Box as="pre" className="trace-fallback-json mono">
      {JSON.stringify(frame, null, 2)}
    </Box>
  </Stack>
);

runtime.features/algorithms/viz/renderers/ArrayV:
// GENERATED from the packaged seed for `arrayview` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/features/algorithms/viz/renderers/ArrayView` after the original module was retired. Regenerate with `npm run emit:records`.
// The `array` structure renderer (#3178, epic #3171) — a `StructureRenderer<"array">` that draws an
// `ArrayFrame` as a row of value-cells (a bar whose height ∝ value, plus the value), stamps each cell's
// `data-op` / `data-mark` via the shared `opStateAttrs` binding, and draws the frame's `cursors` as
// labeled pills above their indices.
//
// The renderer NEVER writes animation CSS — it only stamps the state (see `lib/binding.ts`). The
// `compare` / `swap` / `set` / `sorted` animations are DESIGNER-AUTHORED KitAnimation data (#2942)
// compiled by the kit-motion engine (`arrayViewMotion.ts`), bound to those `[data-op=…]` / `[data-mark=…]`
// data-states. This renderer binds them the standard kit way: its ROOT carries the applying classes
// ({@link ALGO_VIZ_ANIM_CLASSES}) and it ensures the compiled kit CSS is injected; the cells still ONLY
// stamp `data-op` / `data-mark`. Change an animation's data once → every array visualization updates.

import { useEffect } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { opStateAttrs } from "@/features/algorithms/lib/binding";
import type { ArrayFrame } from "@/features/algorithms/lib/trace";
import type { StructureRenderer } from "@/features/algorithms/viz/registry";
import { ALGO_VIZ_ANIM_CLASSES, ensureArrayViewMotion } from "@/features/algorithms/viz/renderers/arrayViewMotion";

/** The numeric magnitude of a cell (strings — non-numeric labels — contribute no bar). */
function magnitude(v: number | string): number {
  return typeof v === "number" && Number.isFinite(v) ? v : 0;
}

/** Group a frame's `cursors` (`{ i: 3, j: 5 }`) by the index they point at, so an index that several
 *  cursors share (e.g. `i === j`) draws all their pills stacked. Names sorted for a stable render. */
function cursorsByIndex(cursors: ArrayFrame["cursors"]): Map<number, string[]> {
  const byIndex = new Map<number, string[]>();
  for (const name of Object.keys(cursors ?? {}).sort()) {
    const at = cursors![name];
    const list = byIndex.get(at) ?? [];
    list.push(name);
    byIndex.set(at, list);
  }
  return byIndex;
}

/**
 * Render an `ArrayFrame` as a row of cells. Each cell carries the `data-op` / `data-mark` state the
 * animations bind to (via {@link opStateAttrs}); its bar height is the value as a fraction of the frame's
 * max magnitude; cursor pills sit above the indices they point at. Pure over the frame — no timing here
 * (the player advances frames; the kit animations fire off the stamped states).
 */
export const ArrayView: StructureRenderer<"array"> = ({ frame }: { frame: ArrayFrame }) => {
  // Ensure the kit's compiled motion CSS (arrayViewMotion.ts) is present — the state-triggered
  // animations bound to the data-states this renderer stamps. Idempotent; no per-render cost.
  useEffect(() => {
    ensureArrayViewMotion();
  }, []);

  const { data, ops, cursors } = frame;
  const max = Math.max(1, ...data.map(magnitude));
  const cursorPills = cursorsByIndex(cursors);

  return (
    // The root carries the kit's applying classes so the `[data-op=…]` / `[data-mark=…]` state rules
    // scope to its cells (the standard kit-binding — the cells themselves only stamp the state).
    <Box className={`array-view ${ALGO_VIZ_ANIM_CLASSES}`} role="list" aria-label="array">
      {data.map((v, i) => {
        const names = cursorPills.get(i) ?? [];
        // A visible floor so a value of 0 / a string still shows a nub instead of nothing.
        const heightPct = Math.max(8, Math.round((magnitude(v) / max) * 100));
        return (
          <Box key={i} className="array-col" role="listitem">
            <Box className="array-cursors" aria-hidden={names.length === 0}>
              {names.map((name) => (
                <Box as="span" key={name} className="array-cursor-pill">
                  {name}
                </Box>
              ))}
            </Box>
            <Box className="array-cell" {...opStateAttrs(ops, i)} title={String(v)}>
              <Box as="span" className="array-bar" style={{ height: `${heightPct}%` }} aria-hidden />
              <Box as="span" className="array-val mono">
                {v}
              </Box>
            </Box>
          </Box>
        );
      })}
    </Box>
  );
};

