 *  this line of work exists to remove. */
const NO_FINDINGS: HealthFinding[] = [];

/** One analysed kit: the findings, plus the exact inputs they were derived from.
 *
 *  Identity, not equality — these are store values, so a reference check is both correct and free. A
 *  CONTENT hash would be the wrong trade: hashing 459 components to avoid re-analysing 459 components
 *  saves nothing.
