 *  NOTE it keys on `soundKit`, the STORE value, and not on the `libResolver` memo derived from it. That
 *  distinction is the whole cache: a `useMemo` is recreated on every mount, so keying on the resolver
 *  could never hit on the one path that matters — navigating back. Caught by the remount test, which
 *  failed against exactly that mistake. */
interface HealthEntry {
  components: readonly unknown[];
  soundKit: unknown;
  findings: HealthFinding[];
}

/** Analysed kits, keyed by `kitId`.
 *
 *  Bounded, because this holds a findings array per kit and the app is long-lived. The bound is small
 *  on purpose: the working set is the technology tabs a user actually switches between, and anything
 *  evicted costs exactly one re-analysis — the behaviour that was unconditional before this cache. */
const HEALTH_CACHE = new Map<string, HealthEntry>();
const HEALTH_CACHE_MAX = 4;

/** Record one kit's findings, evicting the oldest entry past the bound (Map preserves insertion order,
 *  so the first key is the least recently INSERTED — re-analysis re-inserts, which is the freshness we
 *  want without tracking access times). */
function rememberHealth(
  kitId: string,
  components: readonly unknown[],
  soundKit: unknown,
  findings: HealthFinding[],
): void {
  HEALTH_CACHE.delete(kitId);
  HEALTH_CACHE.set(kitId, { components, soundKit, findings });
  while (HEALTH_CACHE.size > HEALTH_CACHE_MAX) {
    const oldest = HEALTH_CACHE.keys().next().value;
    if (oldest === undefined) break;
    HEALTH_CACHE.delete(oldest);
  }
}

// The role dot + kit chip live in kitChrome.tsx (#2420) — shared with the Planner Components pane.

export function DesignsWorkbench() {
  const components = useAppStore((s) => s.components);
  const kits = useAppStore((s) => s.kits);
  // The hydrated kit-THEME collection (#2488) — feeds the preview's palette switcher.
  const kitThemes = useAppStore((s) => s.kitThemes);
