// GENERATED from the packaged seed for `use-glance-faults.ts` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/features/glance/lib/useGlanceFaults` after the original module was retired. Regenerate with `npm run emit:records`.
// useGlanceFaults (#2265) — the unresolved runtime-fault count per project, for the Glance node
// FAULT-health badge. Polls each project's errordb (`bsc errors list --unresolved --json`, #2260) on a
// slow cadence and returns a `{ projectKey → count }` map the workspace merges into the graph nodes.
// Orthogonal to the liveness "live/down" status (#2263): this reads `bsc errors`, that reads
// heartbeats, so the two merge into the node without touching each other.
//
// Degrades to an empty map when a project has no errordb yet (bscJson swallows the reject) — a project
// with zero faults simply shows no badge.
import { useEffect, useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { unresolvedCount, worstFault, type FaultLite } from "@/shared/lib/fleet/faultTriage";

const POLL_MS = 20_000;

interface FaultRow {
  fingerprint: string;
  level: string;
  title: string;
  count: number;
  resolved_at?: number | null;
}

/** The per-project fault summary the health axis reads (#2541): the total unresolved `count`, plus the
 *  worst open fault's `level` (drives the dot colour) and `title` (the bottom-right reason text). */
export interface GlanceFault { count: number; level: FaultLite["level"]; title: string }

/** Unresolved-fault summaries keyed by project plan key. `keys` is the current Glance project set; the
 *  map only carries projects with at least one unresolved fault (absent ⇒ healthy/idle). */
export function useGlanceFaults(keys: string[]): Record<string, GlanceFault> {
  const [counts, setCounts] = useState<Record<string, GlanceFault>>({});
  // Stable join so the poll re-subscribes only when the actual key SET changes, not every render (the
  // parent passes a fresh array each time).
  const keyList = keys.slice().sort();
  const joined = keyList.join("�");
  const keysRef = useRef(keyList);
  useEffect(() => { keysRef.current = keyList; }, [keyList]);

  usePoll(async (isCancelled) => {
    if (isCancelled()) return;
    const targets = keysRef.current;
    if (targets.length === 0) { setCounts({}); return; }
    // #3912: ONE in-process read for the whole set. This was a `Promise.all` of a `bsc errors list`
    // SUBPROCESS per project — at 28 projects on a 20s cadence, ~21 concurrent spawns three times a
    // minute, measured as the single largest consumer of the Tauri command queue (15,806s of invoke
    // time in 72 minutes, p50 8.4s). `src-tauri` already links `errordb`, so the spawns bought nothing.
    // A project absent from the map has no error.db or no open faults — the same "no badge" outcome
    // the per-project read produced by degrading to [].
    const byKey = await safeInvoke<Record<string, FaultRow[]>>("fault_rows_batch", { projectKeys: targets }, {});
    if (isCancelled()) return;
    const entries = targets.map((key): [string, GlanceFault | null] => {
      const faults: FaultLite[] = (byKey?.[key] ?? []).map((r) => ({
        fingerprint: r.fingerprint,
        level: r.level === "warn" || r.level === "fatal" ? r.level : "error",
        title: r.title,
        count: r.count,
        resolvedAt: r.resolved_at ?? null,
      }));
      const worst = worstFault(faults);
      return [key, worst ? { count: unresolvedCount(faults), level: worst.level, title: worst.title } : null];
    });
    setCounts(Object.fromEntries(entries.filter((e): e is [string, GlanceFault] => e[1] !== null)));
  }, POLL_MS, [joined]); // re-subscribe when the key SET changes (via the stable join)

  return counts;
}

