  const themeId =
    (typeof planned?.themeId === "string" && planned.themeId ? planned.themeId : undefined) ?? pin?.themeId;
  if (!kit && !themeId) return undefined;
  return { ...(kit ? { kit } : {}), ...(themeId ? { themeId } : {}) };
