      .filter((o): o is Team => typeof o.id === "string" && !!o.id)
      .map((o) => ({
        id: o.id, name: o.name ?? "Untitled", blurb: o.blurb ?? "",
        positions: o.positions ?? [], relationships: o.relationships ?? [], builtin: o.builtin,
