// into the compact JSON a mobile page renders; the projector hook (useStoreProjector) feeds
// them live store slices and pushes the result through the domain publisher. Pure + typed —
// only `import type` crosses feature boundaries (erased at build), so this module wires no
// runtime coupling and every payload shape is unit-testable from plain fixtures.
//
// Deliberately OUT (maintainer): telemetry/analytics — skill telemetry counters, hook
// analytics, usage charts. Mobile is state + alerts, not dashboards.

import type { ProjectLite, GlanceFault, GHealth } from "@/features/glance";
import type { ProjectLink } from "@/features/glance/lib/projectLinks";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Team } from "@/features/teams";
import type { Persona } from "@/features/personas";
import type { Blueprint, BlueprintTeam } from "@/features/planner/stages/blueprintTypes";
import type { SkillDef } from "@/features/skills/lib/skillsModel";
import type { SkillGroup } from "@/features/skills/lib/skillGroups";
import type { Lesson } from "@/features/skills/lib/lessons";
import type { Kit, ComponentRecord, KitConsumer, KitLibraryRef } from "@/features/designs";
import type { KitThemeRecord } from "@/features/designs/lib/themes";
import type { Automation, AutomationRun } from "@/features/automations/lib/scheduler";
import type { McpServer } from "@/features/mcp/lib/mcpServers";
import type { Hook } from "@/features/mcp/lib/hooks";
import type { AgentProfile, ConsoleSession } from "@/shared/lib/security/agentProfiles";
import type { AuditDisplayRow } from "@/features/logs";
import type { AlertEvent } from "@/features/tunnel/lib/alerts";
import type { GeneralNode } from "@/shared/ui/spec/generalNode";

// ── glance ───────────────────────────────────────────────────────────────────────
// The project network + the drilled project's fleet: the same inputs the desktop Glance
// workspace feeds `buildGlanceData` / `buildRealFleetData`. Mobile rebuilds the graph with
// the vendored shared graph core, so the payload is the MODEL, not layout.

export interface GlancePayload {
  /** Published + local-draft projects, keyed by plan key, with fault badges merged on. */
  projects: ProjectLite[];
  /** The real project→project edges (`bsc project link`). */
  links: ProjectLink[];
  /** The drilled project key (L1 fleet view), or null at the L0 network. Synced drill state. */
  drill: string | null;
  /** The drilled project's fleet plan (streams/director/edges) — derived from {@link fleets}; kept
   *  for the mobile L1 view. Null at the network level or when the drilled fleet isn't loaded. */
  drillFleet: FleetPlan | null;
  /** Every project whose fleet is currently loaded, keyed by project key (#2530) — so ANY project
   *  node can drill into its agents on mobile, not only the currently-drilled one. */
  fleets: Record<string, FleetPlan>;
  /** persona id → resolved session role (#2530) — a stream carries a persona id but no role, and the
   *  glance payload has no personas, so mobile defaulted every agent node to `worker`. This map lets
   *  mobile colour each stream's node by its real role. */
  personaRoles: Record<string, string>;
  /** The remaining THREE `buildGlanceData` inputs (#3743), so mobile rebuilds the FULL cockpit — not just
   *  the project network. Without these mobile fed `buildGlanceData` empty kit/library sets and lost the
   *  UI-kit nodes (#2571) + the algorithm/sound library band (#3133). */
  /** (project, kit) consumer edges — the `uses-kit` band. */
  kitUsage: KitConsumer[];
  /** The kits in use, pared to id + name (a kit node reads its name, else the id). */
  kits: { id: string; name: string }[];
  /** The kit→library `requires` roll-up (`resolveKitLibraryRefs`) — the algorithm/sound band. */
  libraryRefs: KitLibraryRef[];
}

export function buildGlancePayload(input: {
  projects: ProjectLite[];
  links: ProjectLink[];
  faults: Record<string, GlanceFault>;
  drill: string | null;
  /** All loaded fleets, keyed by project key (the projector merges the on-demand drilled fleet in). */
  fleets: Record<string, FleetPlan>;
  /** The persona library — only `id` + `role` are read (start prompts stay desktop-side). */
  personas: { id: string; role: string }[];
  /** (project, kit) consumer edges — the same `kitUsage` the desktop feeds `buildGlanceData` (#3743).
   *  Optional (defaults empty) so a caller without a kit dimension still builds a valid project-only graph. */
  kitUsage?: KitConsumer[];
  /** The kit library — only `id` + `name` are read for the wire (extra Kit fields stay desktop-side). */
  kits?: Kit[];
  /** The kit→library `requires` roll-up (`resolveKitLibraryRefs(components)`, #3133/#3743). */
  libraryRefs?: KitLibraryRef[];
}): GlancePayload {
  return {
    // Mirror the desktop HEALTH overlay (#2541): a project's worst open fault escalates its health to
    // warning/error and carries the fault title as the reason (matches `applyFaultHealth`).
    projects: input.projects.map((p) => {
      const f = input.faults[p.id];
      if (!f) return p;
      const health: GHealth = f.level === "warn" ? "warning" : "error";
      return { ...p, health, reason: f.title, faults: f.count };
    }),
    links: input.links,
    drill: input.drill,
    fleets: input.fleets,
    drillFleet: input.drill ? input.fleets[input.drill] ?? null : null,
    personaRoles: Object.fromEntries(input.personas.map((p) => [p.id, p.role])),
    // The kit + library bands (#3743): pass kitUsage/libraryRefs verbatim; pare kits to id+name so mobile's
    // `buildGlanceData(projects, links, kitUsage, kits, libraryRefs)` renders every node the desktop does.
    kitUsage: input.kitUsage ?? [],
    kits: (input.kits ?? []).map((k) => ({ id: k.id, name: k.name })),
    libraryRefs: input.libraryRefs ?? [],
  };
}

// ── org ──────────────────────────────────────────────────────────────────────────
// The org library (positions + relationships) plus pared persona refs — enough to render the
// org graph and resolve each agent position's persona card (start prompts stay desktop-side).

export interface PersonaRef {
  id: string;
  name: string;
  blurb: string;
  role: string;
  model?: string;
  pooled?: boolean;
  builtin?: boolean;
}

export interface OrgPayload {
  orgs: Team[];
  personas: PersonaRef[];
}

export function buildOrgPayload(input: { orgs: Team[]; personas: Persona[] }): OrgPayload {
  return {
    orgs: input.orgs,
    personas: input.personas.map((p) => ({
      id: p.id, name: p.name, blurb: p.blurb, role: p.role,
      model: p.model, pooled: p.pooled, builtin: p.builtin,
    })),
  };
}

// ── blueprints ───────────────────────────────────────────────────────────────────
// Library CARDS (metadata incl. team presence + the uiKit pin) — NOT each blueprint's full
// stage/team payload — plus the ACTIVE blueprint's embedded team graph, the one graph the
// mobile Blueprints page renders.

export interface BlueprintCard {
  id: string;
  name: string;
  desc: string;
  icon?: string;
  h?: number;
  origin?: string;
  mode?: string;
  tags?: string[];
  uses?: number;
  updatedAt?: string;
  stageCount: number;
  /** The blueprint embeds a team org (#2450). */
  hasTeam: boolean;
  /** The pinned UI kit (#2465), pared to identity. */
  uiKit?: { id: string; version: string; themeId?: string };
  /** The pinned SOUND kit (#3372), pared to identity the same way — the hash stays desktop-side
   *  (mobile renders WHICH kit, it never resolves or verifies one). Additive + optional, so an
   *  older mobile build simply ignores it. */
  soundKit?: { id: string; version: string };
}

export interface BlueprintsPayload {
  active: string;
  library: BlueprintCard[];
  /** The active blueprint's full team graph (positions + relationships), when it has one. */
  activeTeam: BlueprintTeam | null;
}

export function buildBlueprintsPayload(input: {
  blueprints: Blueprint[];
  activeBlueprintId: string;
}): BlueprintsPayload {
  const active = input.blueprints.find((b) => b.id === input.activeBlueprintId);
  return {
    active: input.activeBlueprintId,
    library: input.blueprints.map((b) => ({
      id: b.id, name: b.name, desc: b.desc, icon: b.icon, h: b.h,
      origin: b.origin, mode: b.mode, tags: b.tags,
      uses: b.uses, updatedAt: b.updatedAt,
      stageCount: b.sections.length,
      hasTeam: !!b.team && b.team.positions.length > 0,
      uiKit: b.uiKit ? { id: b.uiKit.id, version: b.uiKit.version, themeId: b.uiKit.themeId } : undefined,
      soundKit: b.soundKit ? { id: b.soundKit.id, version: b.soundKit.version } : undefined,
    })),
    activeTeam: active?.team && active.team.positions.length > 0 ? active.team : null,
  };
}

// ── skills ───────────────────────────────────────────────────────────────────────
// The library + task groups + the active project's PENDING lessons. Telemetry counters
// (invocations/success/tokens/trend) are analytics — dropped on mobile. Prompt bodies are
// desktop-side authoring content — dropped too (cards carry the desc).

export interface SkillCard {
  id: string;
  name: string;
  kind: string;
  source: string;
  desc: string;
  projects: string[];
  enabled: boolean;
  pinned: boolean;
  packaged?: boolean;
}

export interface SkillsPayload {
  skills: SkillCard[];
  groups: SkillGroup[];
  /** The active project's pending lessons (`bsc plan lesson list --status pending`), or null
   *  when there is no active project. */
  lessons: { project: string; pending: Lesson[] } | null;
}

export function buildSkillsPayload(input: {
  skills: SkillDef[];
  groups: SkillGroup[];
  lessons: { project: string; pending: Lesson[] } | null;
}): SkillsPayload {
  return {
    skills: input.skills.map((s) => ({
      id: s.id, name: s.name, kind: s.kind, source: s.source, desc: s.desc,
      projects: s.projects, enabled: s.enabled, pinned: s.pinned, packaged: s.packaged,
    })),
    groups: input.groups,
    lessons: input.lessons,
  };
}

// ── components ───────────────────────────────────────────────────────────────────
// Kit + component SUMMARIES (identity/classification/reuse), not the source bodies —
// `srcText`/`props`/rules stay desktop-side where the Design Studio edits them.
//
// `spec` IS THE EXCEPTION, and the distinction is the whole point rather than an
// inconsistency. `srcText` is React source: the phone cannot run it, and shipping it would be
// shipping CODE. A `spec` is a GeneralNode tree — DATA naming primitives the phone already
// implements natively, which its KitRenderer walks. So the summary/body line is not
// "small vs large", it is "can the phone render this without executing anything".
//
// Without this field mobile's `SpecHost` can only ever draw specs bundled INSIDE the mobile
// repo, which inverts the whole arrangement: screens for the phone would be authored in the
// phone's own tree rather than in this graph. Projecting it is what lets a screen the desktop
// authored reach the device, and what makes a live re-render a rev bump rather than a release.
//
// Size is handled, not ignored: an over-cap domain fragments into `store_state_chunk` frames
// (#3757) against the transport's 48 KB plaintext cap, and mobile reassembles them by rev.

export interface ComponentCard {
  id: string;
  name: string;
  kitId: string;
  role: string;
  version: string;
  used: number;
  tags: string[];
  variants: string[];
  composes: string[];
  builtin?: boolean;
  /** The component's declarative layout tree, when it has one (#3485/#3500). ABSENT for a leaf
   *  primitive or a page not migrated to a spec — and absent must stay absent (never `{}`), so a
   *  mobile selector can tell "no spec authored" from "a spec that renders nothing". */
  spec?: GeneralNode;
}

export interface ComponentsPayload {
  kits: Kit[];
  components: ComponentCard[];
  /** Which project consumes which kit (the propagation consumer index). */
  usage: KitConsumer[];
}

export function buildComponentsPayload(input: {
  kits: Kit[];
  components: ComponentRecord[];
  usage: KitConsumer[];
}): ComponentsPayload {
  return {
    kits: input.kits,
    components: input.components.map((c) => ({
      id: c.id, name: c.name, kitId: c.kitId, role: c.role, version: c.version,
      used: c.used, tags: c.tags, variants: c.variants, composes: c.composes,
      builtin: c.builtin,
      // Passed through verbatim rather than pared: the renderer validates the tree against the
      // manifest on arrival, and a partially-projected node would fail that validation as
      // "malformed" instead of as "unsupported", which is a much worse error to debug on a phone.
      spec: c.spec,
    })),
    usage: input.usage,
  };
}

// ── themes ───────────────────────────────────────────────────────────────────────
// The themes registry (the @data/ui/themes.json shape, hydrated into the store) + the active
// kit theme id — mobile consumes the vars as data (same look, native layout).

export interface ThemesPayload {
  themes: KitThemeRecord[];
  active: string;
}

export function buildThemesPayload(input: { themes: KitThemeRecord[]; active: string }): ThemesPayload {
  return { themes: input.themes, active: input.active };
}

// ── automations ──────────────────────────────────────────────────────────────────
// The automation list with its recent run records (embedded per automation, newest first)
// plus the hooks list. Hook-fire analytics are dropped (analytics are out on mobile).

/** Runs included per automation in the mobile payload (the store itself caps at 25). */
export const AUTOMATION_RUNS_CAP = 10;

export interface AutomationCard {
  id: string;
  name: string;
  armed: boolean;
  when: Automation["when"];
  lastRunAt: number | null;
  nextRunAt: number | null;
  runs: AutomationRun[];
}

export interface HookCard {
  id: string;
  name: string;
  enabled: boolean;
  event: string;
  matcher?: string;
  projects: string[];
}

export interface AutomationsPayload {
  automations: AutomationCard[];
  hooks: HookCard[];
}

export function buildAutomationsPayload(input: {
  automations: Automation[];
  hooks: Hook[];
}): AutomationsPayload {
  return {
    automations: input.automations.map((a) => ({
      id: a.id, name: a.name, armed: a.armed, when: a.when,
      lastRunAt: a.lastRunAt, nextRunAt: a.nextRunAt,
      runs: a.runs.slice(0, AUTOMATION_RUNS_CAP),
    })),
    hooks: input.hooks.map((h) => ({
      id: h.id, name: h.name, enabled: h.enabled, event: h.event,
      matcher: h.matcher, projects: h.projects,
    })),
  };
}

// ── mcp ──────────────────────────────────────────────────────────────────────────
// The MCP server list + which are installed (runnable config present — the same
// `resolveAllInstalledMcp` set the desktop page derives). Env vars stay desktop-side
// (they can carry secrets).

export interface McpCard {
  id: string;
  name: string;
  enabled: boolean;
  transport: string;
  projects: string[];
  url?: string;
  /** The server has a runnable config (in the installed set). */
  installed: boolean;
}

export interface McpPayload {
  servers: McpCard[];
}

export function buildMcpPayload(input: {
  servers: McpServer[];
  /** Ids of the installed set (from `resolveAllInstalledMcp`, which includes built-ins). */
  installedIds: string[];
}): McpPayload {
  const installed = new Set(input.installedIds);
  return {
    servers: input.servers.map((s) => ({
      id: s.id, name: s.name, enabled: s.enabled, transport: s.transport,
      projects: s.projects, url: s.url, installed: installed.has(s.id),
    })),
  };
}

// ── security (#2530 / #3754) ───────────────────────────────────────────────────────
// The least-privilege picture the mobile Security page (#223) renders, READ-ONLY: the always-on
// application roles + the assignable agent profiles (#289 — the permission CONFIG: base policy ·
// command allowlist · per-tool tri-states · write-path scope · network HOST allowlist), a live
// console/pane model, the per-pane role + profile assignments, and recent audit activity (bsc-audit,
// #257). No secrets cross — `net` is a host allowlist (not credentials), and each audit row is a
// short/redacted display row, never a full tool input.
//
// #3754 closes the last mobile-Security gap: the audit `decision` (allow/ask/block) and the
// pane→console join are computed by the DESKTOP's single source of truth (buildAuditRows / the
// launch-gate rules) in the projector, so mobile never re-derives a security verdict.

/** Recent audit rows in the security payload — the desktop log keeps more; mobile shows a phone-sized
 *  window. Sized so the payload (re-pushed every 15s, each row now a full display row rather than a raw
 *  record) stays comfortably under the Noise transport's per-message cap (#3754). */
export const SECURITY_AUDIT_CAP = 50;

export interface SecurityProfileCard {
  id: string;
  name: string;
  category: string;
  desc: string;
  /** Base policy for anything not explicitly listed (deny | ask | allow). */
  mode: string;
  commands: string[];
  /** tool → tier (read/edit/bash/… → deny|ask|allow). */
  tools: Record<string, string>;
  paths: { allow: string[]; deny: string[] };
  /** Allowed network hosts — NOT credentials. */
  net: string[];
  builtin?: boolean;
  /** Swatch colour for the profile chip (#3754). */
  color: string;
  /** "built-in" | "user-defined" | "generated by Planner" — the origin chip (#3754). */
  origin?: string;
  // Application-role only (#3754): present on {@link SecurityPayload.appRoles}, undefined (dropped from
  // the wire JSON) on a plain assignable profile.
  surface?: string;
  surfaceGlyph?: string;
  session?: string;
  owns?: string;
}

/** A console summary (#3754): the INPUTS mobile needs to render "console / pane" and compute a pane's
 *  effective allowlist locally (guaranteed ∪ profile ∪ project ∪ repo — a plain set-merge, not policy
 *  logic). We send the inputs, not the resolved list; only the audit `decision` is desktop-authoritative. */
export interface SecurityConsoleCard {
  id: string;
  name: string;
  repo: string;
  projectAllow: string[];
  repoAllow?: string[];
  panes: { id: string; profileId: string }[];
}

export interface SecurityPayload {
  /** The always-on application singletons (Project Planner, …) the desktop lists FIRST. */
  appRoles: SecurityProfileCard[];
  profiles: SecurityProfileCard[];
  /** Live console/pane model — lets mobile resolve pane→console and the effective allowlist locally. */
  consoles: SecurityConsoleCard[];
  /** paneId → the SessionRole it launched under. Transient — empty before any fleet launch. */
  paneRoles: Record<string, string>;
  /** paneId → assigned agent-profile id. */
  paneProfiles: Record<string, string>;
  /** Recent audit DISPLAY rows (bsc-audit #257 → buildAuditRows), newest first, capped at
   *  {@link SECURITY_AUDIT_CAP}. Each carries the desktop-computed `decision` (allow/ask/block). */
  audit: AuditDisplayRow[];
}

/** Map an AgentProfile to its wire card — the permission config plus the swatch/origin and the
 *  app-role-only fields (undefined on a plain profile, so `JSON.stringify` drops them). */
function toSecurityProfileCard(p: AgentProfile): SecurityProfileCard {
  return {
    id: p.id, name: p.name, category: p.category, desc: p.desc, mode: p.mode,
    commands: p.commands,
    tools: Object.fromEntries(Object.entries(p.tools)),
    paths: { allow: p.paths.allow, deny: p.paths.deny },
    net: p.net.allow,
    builtin: p.builtin,
    color: p.color,
    origin: p.origin,
    surface: p.surface,
    surfaceGlyph: p.surfaceGlyph,
    session: p.session,
    owns: p.owns,
  };
}

export function buildSecurityPayload(input: {
  /** APP_ROLES — the always-on application singletons (rendered first). */
  appRoles: AgentProfile[];
  /** The assignable permission profiles (`s.agentProfiles`). */
  profiles: AgentProfile[];
  /** The live console/pane model, `deriveConsoles(...)` in the projector. */
  consoles: ConsoleSession[];
  paneRoles: Record<string, string>;
  paneProfiles: Record<string, string>;
  /** Pre-computed display rows (`buildAuditRows(...)` in the projector) — carry the desktop `decision`. */
  auditRows: AuditDisplayRow[];
}): SecurityPayload {
  return {
    appRoles: input.appRoles.map(toSecurityProfileCard),
    profiles: input.profiles.map(toSecurityProfileCard),
    consoles: input.consoles.map((c) => ({
      id: c.id, name: c.name, repo: c.repo,
      projectAllow: c.projectAllow,
      repoAllow: c.repoAllow,
      panes: c.panes.map((p) => ({ id: p.id, profileId: p.profileId })),
    })),
    paneRoles: input.paneRoles,
    paneProfiles: input.paneProfiles,
    audit: input.auditRows.slice(0, SECURITY_AUDIT_CAP),
  };
}

// ── alerts ───────────────────────────────────────────────────────────────────────

export interface AlertsPayload {
  alerts: ReadonlyArray<AlertEvent>;
}

export function buildAlertsPayload(inbox: ReadonlyArray<AlertEvent>): AlertsPayload {
  return { alerts: inbox };
}

