import { resolveKitLibraryRefs, useUiActivity, designStudioVisible } from "@/features/designs";
import { loadPendingLessons } from "@/features/skills";
import { resolveAllInstalledMcp } from "@/features/mcp";
import { APP_ROLES } from "@/shared/lib/security/agentProfiles";
