      void listen(logEventName(s), () => { if (!cancelled) void fnRef.current(isCancelled); })
        .then((un) => { if (cancelled) quietly(un()); else uns.push(un); })
        .catch(() => { /* the window went away before the subscription landed */ });
    }
    return () => { cancelled = true; uns.forEach((un) => quietly(un())); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, active, ...deps]);
}

