    const line = slowInvokeLine(label, performance.now() - t0, command);
    if (!line) return;
    // THE SWALLOW MUST COVER A SYNCHRONOUS THROW. This closure runs DEFERRED — `safeInvoke` calls it
    // from `finally` and `fireInvoke` from a `.finally` microtask — so by the time it fires, a test may
    // have torn its Tauri mock down. `invoke` then returns a non-thenable (or throws), `.catch` on that
    // raises immediately, and with nothing on the stack it escapes as an UNCAUGHT EXCEPTION that reddens
    // a run in which every test passed. Third instance of this shape: see `fireInvoke` and log.ts's
    // `drain`. Reporting a slow call must never be able to fail the thing it is measuring.
    try {
      const sent: unknown = invoke("frontend_log", { level: "warn", scope: "perf", message: line });
      if (sent && typeof (sent as PromiseLike<unknown>).then === "function") {
        void (sent as Promise<unknown>).catch(() => {});
      }
