export function probeMatchesRecords(
  probe: ProbeNode[],
  records: Array<Pick<MinimalGhProject, "id" | "updatedAt">>,
): boolean {
  if (probe.length !== records.length) return false;
  const byId = new Map(records.map((r) => [r.id, r.updatedAt]));
