// GENERATED from the packaged seed for `launch-rules.ts` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/shared/lib/session/launchRules` after the original module was retired. Regenerate with `npm run emit:records`.
// Role gate (#219) — launch wiring. Renders a role's capability into the concrete permission
// artifacts a session is launched with: the write-tool `permissions.allow`/`deny` rules
// ({@link roleWriteRules}), whole-tool denies ({@link roleDeniedTools}), the command-prefix denies
// merged into the allowlist ({@link roleDeniedCommands}), and the bsc-agent-native permission doc
// ({@link bscAgentPerms}). Pure enforcement core, free of React / xterm / Tauri. Re-exported from
// `sessionRoles.ts`.

import type { AccessTier, RoleCapability } from "@/shared/lib/session/roleModel";
import { capabilitySurfaces, DB_OWNED_PLAN_FILES, DEP_MANIFEST_FILES, hasScopedWriteCarveOut, isRestrictedRole, mayFileToolingRequest, TOOLING_REQUEST_COMMAND } from "@/shared/lib/session/roleModel";

// ── Launch wiring: write-tool permission rules ──────────────────────────────────

/** The file-mutating tools gated by a WHOLE-TOOL deny (bare tool name, no path). Claude Code has no
 *  `MultiEdit` tool (removed) and a bare `Edit` deny does NOT cover `Write`/`NotebookEdit` — they are
 *  separate tools — so all three must be listed to block every file write (#3534). */
const WRITE_TOOLS = ["Edit", "Write", "NotebookEdit"];

/** A PATH-SCOPED file rule uses ONLY `Edit(<glob>)`: Claude Code matches file-permission rules on the
 *  `Edit` tool alone, and that ONE rule covers every file-editing tool (Write/NotebookEdit). Emitting
 *  `Write(<glob>)`/`NotebookEdit(<glob>)`/`MultiEdit(<glob>)` produces rules Claude Code never matches —
 *  a silent no-op for an allow, and (worse) an unenforced deny (#3534). */
export const editPathRule = (glob: string): string => `Edit(${glob})`;

export interface ToolPermissionRules {
  /** Rules to auto-approve (Claude Code `permissions.allow`). */
  allow: string[];
  /** Rules to block (`permissions.deny`; deny wins over allow). */
  deny: string[];
}

/**
 * Declarative `settings.json` permission rules that encode {@link canWritePath} for
 * the file-write tools at session launch — the write-tool counterpart to
 * {@link roleDeniedCommands}.
 *
 * - `code: "none"` (planner/director/triage) — {@link canWritePath} is always false,
 *   so deny every write tool outright (bare tool names = whole-tool deny).
 * - `code: "write"` with a boundary — auto-approve each `writeGlob` as
 *   `Tool(<glob>)` allow rules (exactly the paths {@link canWritePath} accepts).
 *   Writes outside the boundary fall through to Claude Code's default prompt; a
 *   hard outside-boundary *block* is the PreToolUse-hook follow-on.
 * - `code: "write"` with no boundary yet — no rules (writes follow the default),
 *   since the ownership globs aren't assigned to the pane.
 *
 * {@link canWritePath} stays the authoritative runtime predicate; these rules mirror
 * it into the tools at launch.
 */
export function roleWriteRules(cap: RoleCapability): ToolPermissionRules {
  if (cap.code === "none") {
    // Scoped carve-out (#851): a `code: "none"` role WITH explicit writeGlobs (the director's
    // commons) auto-approves the write tools for EXACTLY those globs. Claude Code's precedence is
    // deny > allow, so the whole-tool deny would mask any narrower allow — instead of denying the
    // bare tools we emit only the per-glob allows. Any write OUTSIDE the commons falls through to
    // the default prompt and is hard-blocked by the bsc-scope hook ({@link scopeWriteGlobs}), so
    // the director can write the commons and is denied all other code writes.
    if (hasScopedWriteCarveOut(cap)) {
      return { allow: cap.writeGlobs.map(editPathRule), deny: [] };
    }
    return { allow: [], deny: [...WRITE_TOOLS] };
  }
  const allow = cap.writeGlobs.map(editPathRule);
  // Role-specific deny set, layered over the write-glob allows (deny wins over allow):
  // - director / planner: the DB-owned plan-state artifacts (#1070) — the plan globs would otherwise
  //   auto-approve a stray `deploy.md`/`phases.json`; force them to the `bsc plan` CLI. The DIRECTOR
  //   is listed because it now carries the planning write surface — omitting it would have handed the
  //   merged role file-level write over exactly the plan state plan.db is supposed to own.
  // - worker: the dependency manifests + lockfiles (#1111) — the planner locks deps once and
  //   publish seeds them, so a worker editing its own manifest is the parallel-redefinition that
  //   collides at integration; a new dep routes through the director.
  const denyFiles = cap.role === "planner" || cap.role === "director" ? DB_OWNED_PLAN_FILES
    : cap.role === "worker" ? DEP_MANIFEST_FILES
    : [];
  const deny = denyFiles.map(editPathRule);
  return { allow, deny };
}

/**
 * Whole-tool denies by role BEYOND the write-path tools (#1036) — currently the sub-agent **Task**
 * tool for **workers**. A worker must not spawn its OWN sub-agents: each spawned agent reads as
 * fresh activity that the always-on coordinator keeps trying to relaunch the worker for (a wake
 * request every poll), and it blurs the worker's lane. A worker does its assigned issue directly;
 * spinning up helper sessions is the director's job. Denied by bare tool name — the same whole-tool
 * deny {@link roleWriteRules} uses for Edit/Write — so it's a hard block at launch, no prompt, no
 * delay. Merged into `denyToolRules` at session launch.
 */
export function roleDeniedTools(cap: RoleCapability): string[] {
  const out: string[] = [];
  if (cap.role === "worker") out.push("Task");
  // Network gate (#1107): `net: "none"` denies the web tools outright at launch — the lever that
  // turns OFF the planner's (or any agent's) live injection surface. `read` (the default) leaves
  // them allowed, with results framed as untrusted data.
  if (cap.net === "none") out.push("WebFetch", "WebSearch");
  return out;
}

// ── Launch wiring: command-allowlist denies ────────────────────────────────────

/** git write subcommand prefixes (the backend wraps each as `Bash(<prefix> *)`). */
const GIT_WRITE_DENY = [
  "git push", "git commit", "git merge", "git rebase", "git reset", "git revert",
  "git cherry-pick", "git tag", "git am", "git apply",
];

/** gh write command prefixes + writing `gh api` methods. */
const GH_WRITE_DENY = [
  "gh issue create", "gh issue edit", "gh issue close", "gh issue reopen",
  "gh issue comment", "gh issue delete", "gh issue lock", "gh issue transfer", "gh issue pin",
  "gh pr create", "gh pr merge", "gh pr close", "gh pr edit", "gh pr comment", "gh pr ready", "gh pr review",
  "gh label create", "gh label edit", "gh label delete",
  "gh release create", "gh release edit", "gh release delete",
  "gh repo create", "gh repo edit", "gh repo delete",
  "gh api --method POST", "gh api --method PATCH", "gh api --method PUT", "gh api --method DELETE",
  "gh api -X POST", "gh api -X PATCH", "gh api -X PUT", "gh api -X DELETE",
];

/** `bsc ui` (component/kit store) mutating verb prefixes (#2470) — denied at `ui: "read"` so a
 *  session can READ the kit it implements against but never redefine it. Includes the deprecated
 *  `bsc component` alias's verbs while that alias lives (#2469); deny-wins keeps these solid over
 *  the baseline's broad `bsc` allow. */
const UI_WRITE_DENY = [
  "bsc ui set", "bsc ui remove", "bsc ui kit set", "bsc ui kit remove",
  "bsc component set", "bsc component remove", "bsc component kit set", "bsc component kit remove",
];

/** File-mutating shell commands denied for a WRITE-LESS role (#2932) — the bash counterpart to the
 *  whole-tool Edit/Write deny in {@link roleWriteRules}. A `code: "none"` role with no scoped write
 *  carve-out writes NOTHING: not via the Edit/Write tools (already denied), and not via bash either —
 *  otherwise (as happened) a session bypasses the tool-deny with `tee`/`cp`/`echo > file` and mutates
 *  the repo (e.g. `src-tauri/data/`, triggering a rebuild). Denies the common file writers; shell
 *  redirection (`>`) can't be prefix-denied and is caught by the always-on `bsc-confine` FS hook.
 *  Carve-out roles (documentor/marketer/a commons director) and writers (planner/worker) are EXCLUDED —
 *  they write their scoped globs via the Write tool, not bash. */
const FILE_WRITE_DENY = [
  "tee", "dd", "truncate", "install", "cp", "mv", "ln", "patch", "sponge",
  "sed -i", "sed --in-place", "perl -i",
  "vi", "vim", "nano", "emacs", "ed", "ex",
];

/**
 * Command-prefix denies to apply at session launch for a role, merged into the
 * session's `deniedCommands` (the backend wraps each as `Bash(<prefix> *)`, and a
 * specific deny overrides the broad `git`/`gh` allow). A first-layer gate: blocks the
 * args-bearing mutating commands while leaving reads alone. `none` tiers deny the tool
 * outright.
 *
 * This is the launch-time allowlist layer; complete subcommand-granular enforcement
 * (incl. no-arg variants) is a PreToolUse hook (follow-on), and the authoritative
 * publish gate is `checkCommand` at the executor call site.
 */
/** The persona store's mutating verbs — architect-only (see {@link roleDeniedCommands}). `rename` is
 *  included because a persona's NAME is how every other surface refers to it, so renaming one out from
 *  under a team is a mutation like any other. */
const PERSONA_WRITE_DENY = ["bsc persona set", "bsc persona remove", "bsc persona rename"];

/**
 * Interpreters a RESTRICTED role may not reach for — the "pipe into an interpreter" case its own
 * spec already forbids in prose.
 *
 * The designer's spec says it outright: "You do **not** have `node`, `python`, `jq` ... and reaching
 * for one will be refused — not as a mistake, but by design: your shell surface is an allow-list."
 * That was PROSE ONLY. Nothing denied an interpreter; it simply was not in the allow-list, so it
 * PROMPTED and was approved. A promise the environment does not keep teaches the opposite of what
 * it says, and the session learns the rule does not apply.
 *
 * MEASURED before writing this: one designer session made 555 Bash calls, 37 of them python — every
 * one post-processing `bsc` JSON (selecting a field, counting a length, looping over ids), and the
 * session had run `which python3 node jq` first, so it went looking for a way around.
 *
 * Written as bare PROGRAM NAMES on purpose. `deny_matches` (bsc-util/src/deny.rs) gives a bare name
 * program-TOKEN semantics: it takes the first word of every pipeline segment and recurses into
 * `sh -c`, so `bsc ui get x | python3 -c '…'` is caught. A `Bash(python3 *)` prefix rule would not
 * have been — and the observed misuse was almost entirely piped, which is exactly the shape a
 * workaround takes.
 *
 * RESTRICTED roles only. A worker legitimately builds and tests; a studio whose entire surface is
 * one store CLI has no use for an interpreter that its spec has not already told it to avoid.
 */
const INTERPRETER_DENY = ["python", "python3", "node", "jq", "perl", "ruby"];

export function roleDeniedCommands(cap: RoleCapability, activeSurfaces: readonly string[] = []): string[] {
  const out: string[] = [];
  // The COMMAND-SURFACE complement (`a-persona-declares-its-command-surfaces`). `bsc` sits in the
  // permission model's `mandatory` tier (`data/permissions/base.json`) — always allowed, every role,
  // every posture — so a role that declares no surfaces reaches ALL of them. A role that DOES declare
  // them is held to exactly that set by denying every active catalog surface it did not name.
  //
  // `activeSurfaces` is the ONE catalog (`bsc surface list --json`), passed in rather than restated:
  // `bsc surface help` says outright that the role join belongs at the consumer, and three plan items
  // already exist for hand-kept copies of this set drifting from what really dispatches.
  //
  // FAIL-OPEN ON AN EMPTY CATALOG, deliberately. The catalog is read from a subprocess, so
  // "unavailable" and "no surfaces exist" are indistinguishable here. Complementing against an empty
  // list denies nothing, which is the safe direction: the alternative would brick every session the
  // moment that read failed. A declared list NARROWS an already-granted surface — it is not the grant.
  //
  // The pattern carries a SPACE, which is load-bearing: `deny_matches` (bsc-util/src/deny.rs) keeps
  // substring semantics for anything that is not a bare program name, so `bsc atlas` matches
  // `bsc atlas list …` while a bare `bsc` would deny the entire CLI. Same shape as the
  // TOOLING_REQUEST_COMMAND deny below, which is the precedent this generalizes.
  const declared = capabilitySurfaces(cap);
  if (declared) {
    for (const surface of activeSurfaces) {
      if (!declared.includes(surface)) out.push(`bsc ${surface}`);
    }
  }
  if (cap.git === "none") out.push("git");
  else if (cap.git === "read") out.push(...GIT_WRITE_DENY);
  if (cap.github === "none") out.push("gh");
  else if (cap.github === "read") out.push(...GH_WRITE_DENY);
  // UI store tier (#2470), rendered like git/gh. FAIL-CLOSED on the tier: only an explicit
  // `"write"` skips the mutating-verb denies, so a capability read from a STALE config-dir
  // override that predates the `ui` field (#2325 floor-merge hazard — the merged role OBJECT can
  // lack it) behaves as `"read"`, never as an accidental grant.
  if (cap.ui === "none") out.push("bsc ui", "bsc component");
  else if (cap.ui !== "write") out.push(...UI_WRITE_DENY);
  // `graph: none` denies the SURFACE, so `none` means for the algorithms store exactly what it means
  // for the component store one line up — a tier rather than a synonym for `read`.
  //
  // Only the `none` arm, deliberately. `ui: read` also denies its mutating COMMANDS here, which buys a
  // launch-time prompt; the algorithms store's write gate lives in the `bsc-graph` binary, and that is
  // strictly stronger — `permissions.deny` is ignored under the bypass posture while the CLI refusal
  // is not (`the-algorithms-graph-has-no-write-gate`).
  if (cap.graph === "none") out.push("bsc graph");
  // A write-less role (code:none, no carve-out) writes NOTHING — deny the file-mutating bash commands
  // too, the counterpart to its whole-tool Edit/Write deny (#2932). Shell redirection (`>`) can't be
  // prefix-denied; the always-on `bsc-confine` FS hook is the complete layer.
  //
  // A RESTRICTED role keeps these denies even though it HAS a carve-out (#3373). Its carve-out is a
  // tool-only staging dir: it writes `scratch/**` with the Write tool and applies it with its one store
  // CLI. It has no business running `cp`/`mv`/`tee`/`sed -i` at all — its spec says in as many words
  // not to reach for bash to sidestep the file rules — so the shell mutation set stays denied. Without
  // this clause the carve-out would silently UN-deny them, widening the session well past the staging
  // dir the design intended.
  const carveOutWritesViaShell = hasScopedWriteCarveOut(cap) && !isRestrictedRole(cap.role);
  if (cap.code === "none" && !carveOutWritesViaShell) out.push(...FILE_WRITE_DENY);
  // The global tooling-request queue (#4000). `bsc` sits in the permission model's `mandatory` tier —
  // ALWAYS allowed, every role, every posture — so without this deny any worker could file straight
  // into the queue a full-capability session drains to edit base-studio-code itself. Not granting it
  // is not enough; only a deny keeps it out, because the hook is the sole layer that fires under
  // bypass (where `permissions.deny` is ignored).
  //
  // The pattern carries a SPACE, which matters: `deny_matches` (bsc-util/src/deny.rs) treats a bare
  // program name as a program-TOKEN match, but keeps substring semantics for anything else — so
  // "bsc request" matches `bsc request new …` while a bare "bsc" would have denied the entire CLI.
  if (!mayFileToolingRequest(cap.role)) out.push(TOOLING_REQUEST_COMMAND);
  // Persona WRITES are the architect's (epic `the-persona-is-the-whole-agent`). The architect is the
  // session that configures personas and their capability BEFORE a director is asked to design a team
  // from them, so every other role is denied the three mutating verbs. Reads stay open to everyone —
  // a worker must still be able to see what it is running as.
  //
  // THIS IS A POLICY, NOT A BOUNDARY, and the distinction is worth stating where it is implemented:
  // these patterns carry SPACES, so `deny_matches` (bsc-util/src/deny.rs) applies substring semantics
  // rather than a program-token match — `bsc  persona set` with two spaces walks straight through —
  // and under the bypass posture `permissions.deny` is ignored entirely, leaving only the hook. What
  // actually holds is the store's own narrow-only clamp (crates/bsc-persona/src/floor.rs), which is a
  // property of the WRITE rather than of the caller and therefore cannot be spoofed or evaded. This
  // deny is here to make the workflow explicit and to stop the accidental case, not to cage anything.
  if (cap.role !== "architect") out.push(...PERSONA_WRITE_DENY);
  // ...and make the restricted spec's "you do not have python" true rather than merely stated. See
  // INTERPRETER_DENY: without this the sentence is prose the environment contradicts, and a session
  // that has been approved for python 37 times has learned which one to believe.
  if (isRestrictedRole(cap.role)) out.push(...INTERPRETER_DENY);
  // DEDUPED: the surface complement above can restate a deny a later clause adds for its own reason —
  // `bsc request` is denied both as an undeclared surface and as the tooling queue — and a doubled
  // entry would ride into every `.claude/settings.json` and `$BSC_DENY_BASH` this feeds.
  return [...new Set(out)];
}

/** The permission doc the `bsc-agent` runtime reads from `$BSC_AGENT_PERMS` (#1078 P3) — the
 *  generic role model rendered to bsc-agent's native shape (vs the Claude `.claude/settings.json`
 *  syntax {@link roleWriteRules}/{@link roleDeniedTools} produce). `code: "none"` denies the
 *  write/edit tools outright; `deny_bash` reuses {@link roleDeniedCommands} (substring-matched by
 *  bsc-agent — coarser than Claude's prefix allowlist); `write_globs` scopes a writer to its lane. */
export interface BscAgentPerms {
  deny_tools: string[];
  deny_bash: string[];
  write_globs: string[];
}

/** Render the role capability to bsc-agent's native permission doc. `granted` are the
 *  GitHub-propagation commands the pane's *flow* permits (from {@link flowGrantedPushCommands}):
 *  the flow owns `git push` / `gh pr create`, so they're lifted from the role denies when it
 *  permits pushing/PRing — mirroring the Claude role↔flow reconciliation (#304) so an `auto-pr`
 *  bsc-agent worker (github:read) can open its own PR. Everything else the role denies stays
 *  denied. With no flow grant (the default), behavior is unchanged.
 *
 *  `cap` may be `null` for a role-less (ad-hoc) bsc-agent console — then only `extraDenyBash`
 *  applies. `extraDenyBash` is the user's global command denylist (`store.deniedCommands`), the
 *  parallel to the `...deniedCommands` the Claude path passes to `ensure_session_settings`; bsc-agent
 *  has no `.claude/settings.json`, so they must ride in here to be enforced. The catastrophic
 *  base floor (sudo / `rm -rf /` / force-push) is NOT listed here — it's an always-on floor inside
 *  the bsc-agent runtime ({@link ../../../../crates/bsc-agent BASE_DANGEROUS_BASH}), so it can't be
 *  dropped by an empty perm doc. */
export function bscAgentPerms(
  cap: RoleCapability | null,
  granted: string[] = [],
  extraDenyBash: string[] = [],
  activeSurfaces: readonly string[] = [],
): BscAgentPerms {
  // The scoped carve-out (#851) applies here too: a `code: "none"` director WITH commons writeGlobs
  // keeps its write tools (scoped to the commons) rather than having them denied outright.
  const carveOut = cap ? hasScopedWriteCarveOut(cap) : false;
  // THE SURFACE COMPLEMENT, which this call used to omit
  // (`a-bsc-agent-session-is-denied-less-than-the-same-role-on-claude`). `roleDeniedCommands`'
  // second argument defaults to `[]`, and an empty catalog denies NOTHING extra — so a persona's
  // undeclared `bsc` surfaces stayed reachable here while the same role on Claude had them denied.
  // MEASURED: a designer was denied `bsc plan`, `bsc skill`, `bsc graph` and `bsc org` on Claude and
  // none of them on this harness.
  //
  // Nothing said the omission was deliberate — this doc explained the flow reconciliation and the
  // user denylist and was silent on surfaces, which is what an argument forgotten at one of two call
  // sites looks like. It is also the ONLY route: `bsc-agent` reaches a surface through its `bash`
  // tool and nowhere else (it registers ten tools and none of them runs a `bsc` noun), so `deny_bash`
  // is what gates it.
  const roleDenies = cap ? roleDeniedCommands(cap, activeSurfaces).filter((d) => !granted.includes(d)) : [];
  return {
    deny_tools: cap && cap.code === "none" && !carveOut ? ["write_file", "edit_file"] : [],
    deny_bash: [...new Set([...roleDenies, ...extraDenyBash.map((c) => c.trim()).filter(Boolean)])],
    write_globs: cap && (cap.code === "write" || carveOut) ? cap.writeGlobs : [],
  };
}

/** The per-store access-scope doc rendered into a gated session's `$BSC_SCOPES` env (#2470) — the
 *  runtime, defense-in-depth twin of the launch-time verb denies above. A store CLI reads it via
 *  `bsc_cli_util::scope_allows_write` and refuses its mutating verbs when the store is scoped
 *  read-only. Explicitly NOT a security boundary (a session owns its own env) — it guards accidents
 *  and non-Claude runtimes (`bsc-agent`, raw shells); {@link roleDeniedCommands} is the boundary.
 *  Currently just `ui`; other stores (`plan`, `skill`, `data`, …) adopt incrementally by adding
 *  their tier here. Missing tier ⇒ `"read"` (the same fail-closed floor as the deny rendering). */
export function sessionScopes(cap: RoleCapability): Record<string, AccessTier> {
  // Both stores. The doc carried exactly ONE key until now, which is why the algorithms store was
  // governed by nothing at all: `bsc-graph` held no `require_write_scope` calls, and there was no tier
  // for one to read (`the-algorithms-graph-has-no-write-gate`).
  //
  // `?? "read"` on each for the same reason `roleCapability` defaults them — a capability that predates
  // an axis must reach the session as the reading tier, never as a grant nobody wrote down.
  return { graph: cap.graph ?? "read", ui: cap.ui ?? "read" };
}

runtime.shared/lib/session/poolPlan.tsx:
// GENERATED from the packaged seed for `pool-plan.ts` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/shared/lib/session/poolPlan` after the original module was retired. Regenerate with `npm run emit:records`.
// The plan for request debugger sessions (#one-request-one-debug-session) — decides, each poll, which
// requests need a session started, which sessions to close, and the reconciled live set.
//
// THE MODEL: 1:1. Every request the app has claimed gets exactly ONE session, bound to it and named for
// it (`debug-studio:req-<id>`), and that session is closed when THAT request resolves. There is no pool,
// no cap, no pacing and no reaper.
//
// WHAT THIS REPLACES, AND WHY EACH PIECE WENT. #3535 ran a WARM POOL: generic sessions that claimed work
// after launching, paced one-at-a-time and capped at three total.
//   * The CLAIM RACE is gone because the app claims first and spawns for what it got, so a session never
//     competes for its own work. `bsc request claim` takes the OLDEST open request and is atomic, which
//     is what makes "claim, then spawn for the id it returned" safe against the standing debug session
//     doing the same thing — whoever claims first has it, and the other simply sees it held.
//   * The REAPER (`pollsWarming`/`MAX_WARM_POLLS`) is gone with it. It existed solely to clean up a
//     session that launched, lost the race and would otherwise idle forever with nothing to do. An
//     assigned session always has work.
//   * The PACING is gone: it throttled how fast the pool grew toward a cap, and there is no cap.
//   * The CAP is gone BY DECISION, not by oversight. #3535's cap existed so "a never-resolving request
//     must never be able to fill the machine with debuggers"; at 1:1 the concurrency IS the number of
//     unresolved claimed requests, which the maintainer accepted on the grounds that this queue stays
//     small (44 requests all-time, 4 open when this shipped). If it ever grows, the fix is a queue in
//     front of the spawn — not a return to claiming, which is what made a session's identity meaningless.
//
// PURE and separate from the launcher (mirrors #3498's planner/launcher split): every rule that bounds
// blast radius is here and exhaustively testable without starting a single session. The mount obeys it.

import { autoSpawnDecision, AUTO_SPAWNABLE_ROLE } from "@/shared/lib/session/autoSpawn";
// ABSOLUTE, not `./requestSpawn`: that module has no file — it is a graph record with `provides`, and
// only the `@/…` specifier resolves to it (through tsconfig paths + the emitted record cache).
import { requestPaneId, requestIdFromPaneId } from "@/shared/lib/session/requestSpawn";

/** A request row as `bsc request list --json` returns it (the fields the plan reads). */
export interface RequestRow {
  id: number;
  /** `open` (nobody holds it) · `claimed` (a session holds it) · `resolved` (done). */
  status: string;
  /** The pane id of the session holding a claimed request (#3535 `claimed_by`). */
  claimedBy?: string | null;
}

/** One live request session. Its `paneId` encodes the request, so the id is not stored twice. */
export interface RequestSession {
  paneId: string;
}

export interface RequestSessionPlanInput {
  /** The full request list (`bsc request list --json`), any status. */
  requests: RequestRow[];
  /**
   * The sessions that are ACTUALLY LIVE right now — derived from the app's PTY state, never a set the
   * caller has been remembering.
   *
   * `close` below is computed EXCLUSIVELY from this list, so whatever is missing here can never be
   * closed. The mount used to pass a `useState([])` it accumulated as it started sessions, and that
   * state dies with the component: after any remount — a workspace change, an app restart — it was `[]`,
   * `close` was therefore always `[]`, and every session already running was orphaned with its `claude`
   * process live forever. Measured: request #104 resolved at 22:28:06 and its pane was still up at
   * 22:35 against a 20s poll.
   *
   * A remembered set cannot be right here by construction: this plan's whole job is to reconcile
   * INTENT against REALITY, and half of it was reading the intent twice.
   */
  sessions: RequestSession[];
  /** The Settings toggle (`autoSpawnDebugSessions`). Anything but `true` is off. */
  enabled: boolean | null | undefined;
}

export interface RequestSessionPlan {
  /** Requests that are claimed for us and have no session yet — start one per id, all of them, now. */
  start: number[];
  /** Pane ids to CLOSE: their request resolved, vanished, or the gate turned off. */
  close: string[];
  /** Every still-live session. The mount replaces its tracked set with this, then appends what it starts. */
  sessions: RequestSession[];
  /** When starting nothing, why — so a stalled queue is diagnosable, never a silent non-decision. */
  reason?: string;
}

/**
 * Plan the request sessions for one cycle. Pure — starts and stops nothing.
 *
 * @param input the queue, the live sessions, and the auto-spawn gate.
 * @returns which requests need a session, which panes to close, and the reconciled live set.
 *
 * Steps:
 *  1. **Gate.** Auto-spawn off ⇒ start nothing and CLOSE every session, carrying the gate's own reason.
 *  2. **Reconcile.** A session survives only while its request is still unresolved and still present; a
 *     session whose request resolved (or was removed outright) is closed.
 *  3. **Start.** Every CLAIMED request with no live session gets one. All of them in the same cycle —
 *     there is nothing to pace against.
 *
 * `open` requests are deliberately NOT started: an unclaimed request is one nobody holds, and the app
 * claims it (atomically, obtaining the id) BEFORE asking for a session. Planning off `claimed` is what
 * keeps this pure — the claim is the side effect, and it stays in the mount.
 */
export function planRequestSessions(input: RequestSessionPlanInput): RequestSessionPlan {
  const gate = autoSpawnDecision({ role: AUTO_SPAWNABLE_ROLE, enabled: input.enabled });
  if (!gate.allowed) {
    return { start: [], close: input.sessions.map((s) => s.paneId), sessions: [], reason: gate.reason };
  }

  // The requests still worth holding a session for: anything IN FLIGHT, not resolved. A request that
  // VANISHED from the list (`bsc request remove`, or a prune) is absent here too, which is what closes
  // its session — an unknown id must not keep a session alive forever.
  //
  // `claimed` alone was wrong once `land` existed (#a-debug-session-strands-its-work). A landed request
  // is mid-merge and a verifying one is waiting on the filer's verdict — and a FAILED verdict hands the
  // work straight back to that same session. Closing the pane at `landed` would kill the debugger in the
  // middle of its own landing and leave nothing for a `--fail` to return to, which is the one outcome
  // the loop exists to make survivable. Mirrors `Request::is_in_flight()` on the Rust side; the two are
  // the same predicate and must not drift.
  const IN_FLIGHT = new Set(["claimed", "landed", "verifying"]);
  const liveIds = new Set(input.requests.filter((r) => IN_FLIGHT.has(r.status)).map((r) => r.id));

  const kept: RequestSession[] = [];
  const close: string[] = [];
  for (const s of input.sessions) {
    const id = requestIdFromPaneId(s.paneId);
    if (id != null && liveIds.has(id)) kept.push(s);
    else close.push(s.paneId);
  }

  const held = new Set(kept.map((s) => requestIdFromPaneId(s.paneId)));
  const start = [...liveIds].filter((id) => !held.has(id)).sort((a, b) => a - b);

  return {
    start,
    close,
    sessions: kept,
    reason: start.length === 0 ? (liveIds.size === 0 ? "no claimed requests" : "every claimed request already has a session") : undefined,
  };
}

/** The pane a request's session runs in — re-exported so the mount has one import for the plan + its ids. */
export { requestPaneId };

