    <Box className={className ? `screen ${className}` : "screen"}>
      <Box className="screen-page">
        {!pageOverride && (
          <TabBar
            tabs={tabs}
            activeId={active}
            onSelect={onSelect}
            onReorder={onReorder}
            onTearOff={onTearOff}
            onAdd={onAdd}
            onClose={onClose}
            onRename={onRename}
