          <PageBoundary
            page={pageOverride ?? active}
            hint="The other pages still work: pick one from the tabs above, or press Ctrl+← / Ctrl+→."
          >
            {children}
          </PageBoundary>
        </Box>
      </Box>
      {overlay}
    </Box>
  );
}

