  setVp: (el: HTMLDivElement | null) => void;
  /** Backdrop mousedown → pan. Bails on a `[data-node]` press (the node owns its gesture). */
  onCanvasDown: (e: React.MouseEvent) => void;
  /** Fit the whole world in the viewport and center it. */
