  const spec = SPEC_BY_NAME.get(node.type);
  const props: Record<string, unknown> = {};
  for (const [name, value] of Object.entries(node.props ?? {})) {
    const declared = spec?.props.find((p) => p.name === name);
    if (declared?.type === "function") {
